practice.solution:
SELECT origin FROM flights WHERE destination = 'JFK' ORDER BY origin;

WITH RECURSIVE sources(airport) AS (
    SELECT origin FROM flights WHERE destination = 'JFK'
    UNION
    SELECT f.origin
    FROM sources AS s
    JOIN flights AS f ON f.destination = s.airport
)
SELECT airport FROM sources ORDER BY airport;
